const item = $input.first().json.body ?? $input.first().json;
const columnValues = {
  // TODO: reemplaza estos IDs de columna por los reales del tablero "VictorIA Profesional" en Monday
  text_correo: item.correo,
  text_telefono: `+${item.lada} ${item.telefono}`,
  text_empresa: item.empresa,
  text_ciudad: item.ciudad,
  text_tipo_organizacion: item.tipoOrganizacion || item.seleccion || "",
  status_lead: { label: "Nuevo Lead" }
};
return [{
  json: {
    ...item,
    mondayItemName: item.nombre,
    mondayColumnValues: JSON.stringify(columnValues)
  }
}];
